import unittest

import db
from dao import find_orders


class FindOrdersTest(unittest.TestCase):
    def setUp(self):
        self.conn = db.seed(db.connect())

    def test_returns_matching_orders_for_tenant(self):
        rows = find_orders(self.conn, "acme", "paid")
        self.assertEqual(sorted(r[0] for r in rows), [1, 2])

    def test_scoped_to_tenant(self):
        rows = find_orders(self.conn, "acme", "paid")
        self.assertTrue(all(r[1] == "acme" for r in rows))

    def test_filters_by_status(self):
        rows = find_orders(self.conn, "acme", "pending")
        self.assertEqual([r[0] for r in rows], [3])

    def test_rows_are_ordered_by_order_id(self):
        rows = find_orders(self.conn, "acme", "paid")
        self.assertEqual([r[0] for r in rows], [1, 2])

    def test_returns_full_row_shape(self):
        rows = find_orders(self.conn, "globex", "paid")
        self.assertEqual(rows, [(4, "globex", "Globex LLC", 5000, "paid")])

    def test_unknown_status_returns_empty_list(self):
        self.assertEqual(find_orders(self.conn, "acme", "refunded"), [])

    def test_unknown_tenant_returns_empty_list(self):
        self.assertEqual(find_orders(self.conn, "initech", "paid"), [])


class FindOrdersInjectionTest(unittest.TestCase):
    """``tenant_id``/``status`` arrive from the request, so they must be treated
    as data, never as SQL."""

    def setUp(self):
        self.conn = db.seed(db.connect())

    def test_status_cannot_bypass_tenant_filter(self):
        rows = find_orders(self.conn, "acme", "paid' OR '1'='1")
        self.assertEqual(rows, [])

    def test_tenant_cannot_bypass_status_filter(self):
        rows = find_orders(self.conn, "acme' OR '1'='1", "paid")
        self.assertEqual(rows, [])

    def test_status_cannot_read_other_tenants(self):
        rows = find_orders(self.conn, "acme", "paid' UNION SELECT order_id, tenant_id, customer, amount, status FROM orders --")
        self.assertEqual(rows, [])

    def test_cannot_exfiltrate_api_tokens(self):
        payload = (
            "paid' UNION SELECT id, name, token, id, name FROM api_tokens --"
        )
        rows = find_orders(self.conn, "acme", payload)
        self.assertEqual(rows, [])

    def test_stacked_statements_are_not_executed(self):
        rows = find_orders(self.conn, "acme", "paid'; DROP TABLE orders; --")
        self.assertEqual(rows, [])
        remaining = self.conn.execute("SELECT COUNT(*) FROM orders").fetchone()[0]
        self.assertEqual(remaining, len(db.SAMPLE_ORDERS))


if __name__ == "__main__":
    unittest.main()
